const hasIntersectingEdit = (a, b) => {
        if (!a.length || !b.length) {
            return false;
        }
        // quick exit if the list of ranges are completely unrelated [O(n)]
        const mergedA = a.reduce((acc, val) => { return $gD.plusRange(acc, val.range); }, a[0].range);
        if (!b.some(x => { return $gD.intersectRanges(mergedA, x.range); })) {
            return false;
        }
        // fallback to a complete check [O(n^2)]
        for (const edit of a) {
            for (const otherEdit of b) {
                if ($gD.intersectRanges(edit.range, otherEdit.range)) {
                    return true;
                }
            }
        }
        return false;
